/** Technology name as written in the resume → icon key. First matching rule wins. */
const RULES: [RegExp, string][] = [
  [/^php ?unit/i, 'neutral'],
  [/^php/i, 'php'],
  [/^symfony/i, 'symfony'],
  [/^laravel/i, 'laravel'],
  [/^node/i, 'nodedotjs'],
  [/^python/i, 'python'],
  [/^mysql|^mariadb/i, 'mysql'],
  [/^postgres/i, 'postgresql'],
  [/^redis/i, 'redis'],
  [/^bigquery/i, 'googlebigquery'],
  [/react/i, 'react'],
  [/^vue/i, 'vuedotjs'],
  [/^nuxt/i, 'nuxtdotjs'],
  [/^ionic capacitor|^capacitor/i, 'capacitor'],
  [/^ionic/i, 'ionic'],
  [/^html/i, 'html5'],
  [/^typescript/i, 'typescript'],
  [/^javascript/i, 'javascript'],
  [/^tailwind/i, 'tailwindcss'],
  [/^android|^kotlin/i, 'android'],
  [/cordova|phonegap/i, 'apachecordova'],
  [/^flutter/i, 'flutter'],
  [/^docker/i, 'docker'],
  [/^jenkins/i, 'jenkins'],
  [/^github actions/i, 'githubactions'],
  [/^github/i, 'github'],
  [/^git/i, 'git'],
  [/^aws|amazon/i, 'amazonwebservices'],
  [/^linux/i, 'linux'],
  [/^debian/i, 'debian'],
  [/nginx/i, 'nginx'],
  [/^traefik/i, 'traefikproxy'],
  [/^jest/i, 'jest'],
  [/^cypress/i, 'cypress'],
  [/^selenium/i, 'selenium'],
  [/kafka/i, 'apachekafka'],
  [/^fcm|firebase/i, 'firebase'],
  [/^graphql/i, 'graphql'],
  [/^rest|openapi/i, 'openapiinitiative'],
  [/websocket/i, 'socketdotio'],
  [/^sentry/i, 'sentry'],
  [/^stripe/i, 'stripe'],
  [/^jira/i, 'jira'],
  [/^drupal/i, 'drupal'],
  [/^wordpress/i, 'wordpress'],
  [/^akamai/i, 'akamai'],
  [/^doctrine/i, 'doctrine'],
  [/^jwt/i, 'jsonwebtokens'],
  [/^openid/i, 'openid'],
]

export function techIcon(name: string): string {
  const key = RULES.find(([re]) => re.test(name.trim()))?.[1] ?? 'neutral'
  return TECH_PATHS[key] ?? TECH_PATHS.neutral!
}
